from rdkit import Chem
mol = Chem.MolFromMolFile('ligand.mol')
central = {3, 22, 21, 20, 19, 4}
flankA  = {6, 7, 12, 13, 18, 5}
flankB  = {24, 25, 30, 31, 36, 23}

def linking(bondset1, bondset2):
    for b in mol.GetBonds():
        i, j = b.GetBeginAtomIdx(), b.GetEndAtomIdx()
        if (i in bondset1 and j in bondset2) or (i in bondset2 and j in bondset1):
            return (i, j)

linkA = linking(central, flankA)
linkB = linking(central, flankB)
print("central-flankA bond:", linkA)
print("central-flankB bond:", linkB)

# For each flanking ring, find ipso (in ring, bonded to central), ortho carbons and their Hs
for name, link, ring in [("A", linkA, flankA), ("B", linkB, flankB)]:
    cen, ips = link if link[0] in central else (link[1], link[0])
    print(f"Ring {name}: central C={cen}, ipso C={ips}")
    ipso_atom = mol.GetAtomWithIdx(ips)
    for nb in ipso_atom.GetNeighbors():
        ni = nb.GetIdx()
        if ni in ring and nb.GetSymbol() == 'C':
            hs = [h.GetIdx() for h in nb.GetNeighbors() if h.GetSymbol() == 'H']
            print(f"   ortho C={ni}  H={hs}")
