import numpy as np, json
idx=json.load(open('idx.json'))
def load_xyz(fn):
    lines=open(fn).read().splitlines()
    syms=[]; coords=[]
    for ln in lines[2:]:
        p=ln.split(); syms.append(p[0]); coords.append([float(p[1]),float(p[2]),float(p[3])])
    return syms, np.array(coords)
syms, xyz = load_xyz('opt1.xyz')
from collections import Counter
print("formula check:", Counter(syms))

# covalent radii for bond detection
rad={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'P':1.07,'Ir':1.41}
nbonds=Counter()
short=[]
n=len(syms)
for i in range(n):
    for j in range(i+1,n):
        dij=np.linalg.norm(xyz[i]-xyz[j])
        rc=rad[syms[i]]+rad[syms[j]]
        if dij < rc+0.35:
            nbonds[syms[i]+'-'+syms[j]]+=1
        elif dij < (rad[syms[i]]+rad[syms[j]])*0.9:
            short.append((i,j,syms[i],syms[j],round(dij,2)))
print("bond counts:", dict(nbonds))
print("suspicious short contacts:", short[:20])

# P coordination
P=idx['P']
print("\nP neighbors (dist<2.2):")
for i in range(n):
    dij=np.linalg.norm(xyz[P]-xyz[i])
    if i!=P and dij<2.2: print(f"  {syms[i]}:{i} {dij:.3f}")
# Ir coordination
print("\nIr neighbors (dist<2.6):")
for i in range(n):
    dij=np.linalg.norm(xyz[0]-xyz[i])
    if i!=0 and dij<2.6: print(f"  {syms[i]}:{i} {dij:.3f}")
